// Arduino Sketch
#include <Servo.h>

Servo esc;

void setup() {
  esc.attach(9);       // Сигнальный провод ESC -> D9

  esc.writeMicroseconds(1000); // Минимальный газ
  delay(3000);                 // Инициализация ESC
}

void loop() {
  // Плавно увеличиваем обороты
  for (int throttle = 1000; throttle <= 1800; throttle += 10) {
    esc.writeMicroseconds(throttle);
    delay(50);
  }

  delay(2000);

  // Плавно уменьшаем обороты
  for (int throttle = 1800; throttle >= 1000; throttle -= 10) {
    esc.writeMicroseconds(throttle);
    delay(50);
  }

  delay(2000);
}
